window.bookSummaryJSON = "<p><b>One mage</b>: Bel Adams–part demon, gun shy about being rejected by one again, needs a familiar.</p> <p><b>One familiar:</b> Nico di Rossi–Army Ranger, needs a change of pace and a new purpose in life, is a golden retriever in human form (though not literally).</p> <p><b>Plus one familiar</b>: Garen Dallarosa–Secret Service, part gargoyle, needs his ex-lover Nico back.</p> <p>One second chance–all for the taking.</p>"; 
